  U.addCall(rec, call);
  rec.tokens.input += callTokens.input;
  rec.tokens.output += callTokens.output;
  save(rec);
  if (ctl.cancelled) throw fail("cancelled", "Build cancelled.");
  if (!result) {
    log("error", "claude produced no result", { id: rec.id, code: r.code, err: r.err.slice(-2000) });
    const authish = /auth|401|403|login|credit|quota|rate.?limit|overloaded/i.test(r.err);
    const e = fail(r.timedOut ? "timeout" : "ai_unavailable", r.timedOut ? "The AI took too long on this one. Try a smaller request." : "The AI builder is unavailable right now. Please try again in a few minutes.", authish ? "AI service error" : r.err.slice(-1500));
    // Cyrus capacity: a session/rate limit or overload is "try later" (the build waits in line), not a failure
    if (!r.timedOut && CAP.isAiLimit(r.err)) e.limit = true;
    throw e;
  }
  // any real answer (even a refusal or a cap) means the AI backend is reachable again: close the circuit breaker
  if (!(result.is_error && CAP.isAiLimit(result.result || result.subtype))) BRK.success();
  if (result.subtype === "error_max_budget_usd") throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request or split it into two plugins.");
  // The model provider's own safeguard blocked the request (seen with Sonnet 5.5 on
  // the backdoor / env-dump eval prompts): that is a refusal, not an outage.
  if (result.is_error && /safeguards flagged|\[cyber\]|usage polic/i.test(String(result.result || ""))) {
    throw fail("refused", "We can't build this one. It goes against our plugin safety rules.", String(result.result).slice(0, 300));
  }
  if (result.is_error && result.subtype !== "error_max_turns") {
    const e = fail("ai_unavailable", "The AI builder hit an error. Please try again in a few minutes.", String(result.result || result.subtype).slice(0, 1500));
    if (CAP.isAiLimit(result.result || result.subtype)) e.limit = true;
    throw e;
  }
  return result;
}

// One very cheap Haiku call (no tools, one turn). `kind` names it in the usage record.
async function haikuAsk(rec, ctl, system, text, kind) {
  const args = ["-p", "--output-format", "json", "--tools", "", "--strict-mcp-config", "--settings", SETTINGS,
    "--model", cliModel(R.HAIKU), "--max-turns", "1", "--max-budget-usd", "0.05", "--system-prompt", system, "--", `<request>\n${text}\n</request>`];
  const cwd = path.join(WORK, `${rec.id}-${kind}`);
  fs.mkdirSync(cwd, { recursive: true });
  // One-line answers: no extended thinking (a measured guard call spent 1,358 output tokens and 14 s thinking before a one-word verdict).
  const env = childEnv(true); env.MAX_THINKING_TOKENS = "0";
  const r = await run("claude", args, { cwd, env, timeout: 60000, track: ctl });
  ctl.child = null;
  rmrf(cwd);
  let j = null; try { j = JSON.parse(r.out); } catch { /* fall through */ }
  const cost = j && typeof j.total_cost_usd === "number" ? j.total_cost_usd : 0;
  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
  const ju = (j && j.usage) || {};
  const call = { at: now(), kind, route: null, model: R.HAIKU, resolvedModel: R.HAIKU, costUsd: cost, turns: j ? j.num_turns : null, durationMs: j ? j.duration_ms : null, subtype: j ? j.subtype : null, exit: r.code,
    tokens: { input: (ju.input_tokens || 0) + (ju.cache_creation_input_tokens || 0) + (ju.cache_read_input_tokens || 0), cacheRead: ju.cache_read_input_tokens || 0, output: ju.output_tokens || 0, uncached: ju.input_tokens || 0 } };
  rec.aiCalls.push(call);
  U.addCall(rec, call);
  return j && typeof j.result === "string" ? j.result : null;
}

// Cyrus mod planner (POST /plan): one Haiku turn, no tools, no thinking, no build record. Returns the raw text; the
// portal validates it (zod) and falls back to its keyword rules on anything invalid.
let planSeq = 0;
async function planWithHaiku(body) {
  const args = ["-p", "--output-format", "json", "--tools", "", "--strict-mcp-config", "--settings", SETTINGS,
    "--model", cliModel(R.HAIKU), "--max-turns", "1", "--max-budget-usd", "0.05", "--system-prompt", PLN.PLANNER_PROMPT, "--", PLN.plannerInput(body)];
  const cwd = path.join(WORK, `plan-${process.pid}-${++planSeq}`);
  fs.mkdirSync(cwd, { recursive: true });
  const env = childEnv(true); env.MAX_THINKING_TOKENS = "0";
  const t0 = Date.now();
  try {
    const r = await run("claude", args, { cwd, env, timeout: 30000 });
    let j = null; try { j = JSON.parse(r.out); } catch { /* invalid: the portal falls back */ }
    return { text: j && typeof j.result === "string" ? j.result : null, costUsd: j && typeof j.total_cost_usd === "number" ? j.total_cost_usd : 0, ms: Date.now() - t0 };
  } finally { rmrf(cwd); }
}

