// Answers simple|standard|complex (MB_CLASSIFIER=haiku).
async function classifyWithHaiku(rec, ctl, text) {
  const out = await haikuAsk(rec, ctl, R.CLASSIFIER_PROMPT, text, "classify");
  return out ? (out.toLowerCase().match(/simple|standard|complex/) || [null])[0] : null;
}

// The intake guard (MB_GUARD): one Haiku call over the customer's text BEFORE the main model sees it. It also rates the
// difficulty, so it replaces the separate classifier call when both would run. A refusal costs a fraction of a cent and
// never reaches the main model. It is a filter, not the boundary: the main model has no shell or network, only
// workspace-scoped file tools, and everything it writes is compiled and bytecode-scanned afterwards.
async function guardRequest(rec, ctl) {
  if (R.CFG.guard === "off") return;
  const text = rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt;
  let verdict = null;
  // Cyrus recipe memory (MB_RECIPES=1, fresh builds): the same call names up to two archetypes from a closed list
  const archIds = RCP.enabled() && !rec.baseBuildId && !rec.imported ? RCP.guardArchetypes() : [];
  let answer = null;
  try { answer = await haikuAsk(rec, ctl, archIds.length ? R.guardPromptWithArchetypes(archIds) : R.GUARD_PROMPT, text, "guard"); verdict = R.parseGuard(answer); } catch { verdict = null; }
  if (verdict && verdict.verdict === "allow" && archIds.length) rec.guardArchetypes = R.parseGuardArchetypes(answer, archIds);
  if (!verdict) {
    event(rec, rec.status, "Intake check unavailable, continuing");
    rec.guard = { verdict: "error" };
    if (R.CFG.guard === "strict") throw fail("unavailable", "We couldn't check this request right now. Please try again in a minute.");
    return;
  }
  rec.guard = verdict;
  if (verdict.verdict === "refuse") {
    throw fail("refused", "We can't build this one. It doesn't read like a Minecraft plugin request, or it goes against our plugin safety rules.", `guard:${verdict.code}`);
  }
  if (verdict.class) rec.guardClass = verdict.class;
}

    if (!imOn(rec)) { const t = IMS.snapshotItemModelSpecs(ws); for (const [k, v] of t) snap.set(k, v); if (t.size) event(rec, rec.status, `Keeping ${t.size} existing item model state spec${t.size > 1 ? "s" : ""} unchanged`); }
    if (!cfOn(rec)) { const t = CFG.snapshotConfigSchema(ws); for (const [k, v] of t) snap.set(k, v); }
    if (!creOn(rec)) { const t = CR.snapshotCreatureSpecs(ws); for (const [k, v] of t) snap.set(k, v); if (t.size) event(rec, rec.status, `Keeping ${t.size} existing animated creature${t.size > 1 ? "s" : ""} unchanged`); }
    if (snap.size) keptSpecs.set(rec.id, snap);
}

async function runBuild(rec) {
  const ctl = { child: null, cancelled: false, assets: LA.ENABLED() ? LA.newLog() : null };
  running.set(rec.id, ctl);
  const started = Date.now();
  rec.startedAt = now();
  const ws = path.join(WORK, rec.id);
  const finalWs = path.join(dirOf(rec.id), "ws");
  const killer = setTimeout(() => { ctl.cancelled = true; ctl.timeout = true; if (ctl.child) ctl.child.kill("SIGKILL"); }, BUILD_TIMEOUT_MS);
  let retryAt = 0; // Cyrus capacity: set when an AI limit sends this build back in line instead of failing it
  try {
    rmrf(ws);
    // Fresh builds have nothing to search: Read (reference images) + Write + Edit only.
    rec.toolset = !rec.baseBuildId && LEAN_TOOLS ? FRESH_TOOLS : FULL_TOOLS;
    if (rec.bank) { await runBank(rec, ctl, ws); return; }
    if (rec.reuseOf) {
      if (await tryReuse(rec, ctl, ws)) return;
      // Anything unexpected: forget the match and build normally.
      event(rec, rec.status, "Building it fresh instead");
      rec.reusedFrom = null; rec.reuseFailed = rec.reuseOf; rec.reuseOf = null;
      rec.attempts = 0; rec.safety = null; rec.route = null;
      rmrf(ws);
    }
    if (rec.baseBuildId) {
      const baseWs = path.join(dirOf(rec.baseBuildId), "ws");
      if (!fs.existsSync(baseWs)) throw fail("bad_request", "The earlier build this change is based on is no longer available.");
      copyDir(baseWs, ws, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === baseWs));
      setStage(rec, "planning", "Reading your existing plugin and planning the change");
    } else {
      copyDir(TEMPLATE, ws);
      setStage(rec, "planning", "Planning the plugin from your description");
    }
    keepUnchangedSpecs(rec, ws);

    await guardRequest(rec, ctl);
    rec.route = await chooseRoute(rec, ctl);
    rec.model = rec.route.models.generate;
    save(rec); // route + models live in rec.route / rec.aiCalls, never in customer-visible events
    const refs = (rec.references || []).map((r) => ({ path: path.join(ws, "reference", refFile(r)), name: r.name }));
    // Cyrus recipe memory (MB_RECIPES=1): verified patterns for this request in the first user turn; a deterministic holdback
    // gets none (recorded either way so the A/B can be measured). Off = nothing recorded, the prompt is byte-identical.
    let recipeText = "";
    { const rb = RCP.forBuild(rec); if (rb) { rec.recipes = rb.record; recipeText = rb.block; if (rb.record.injected) event(rec, rec.status, `Using ${rb.record.ids.length === 1 ? "a tested pattern" : `${rb.record.ids.length} tested patterns`} for this kind of mod`); } }
    // Cyrus workspace map (MB_WORKSPACE_MAP=1): an outline of the project already in the working directory goes into the first turn
    // of a change build, so the model does not spend its first turns listing and reading files. Recorded on the build either way.
    let workspaceMap = "";
    if (rec.baseBuildId && WM.enabled()) {
      try {
        const wm = WM.build(ws, { YAML });
        if (wm) { workspaceMap = wm.text; rec.workspaceMap = { tokens: wm.tokens, level: wm.level, files: wm.files, types: wm.types, truncated: wm.truncated }; }
      } catch (e) { log("warn", "workspace map failed", { id: rec.id, err: String(e) }); }
    }
    // Cyrus requirements ledger: a change build is told, compactly, what the plugin already does (checked against its files)
    let ledgerBlock = "";
    if (rec.baseBuildId && !rec.imported && LEDGER.enabled()) {
      try { ledgerBlock = LEDGER.promptBlock(baseLedgerOf(rec.baseBuildId)); if (ledgerBlock) rec.ledgerInjected = ledgerBlock.split("\n").filter((l) => l.startsWith("- ")).length; } catch (e) { log("warn", "ledger prompt failed (ignored)", { id: rec.id, err: String(e && e.message) }); }
    }
    const promptRec = workspaceMap ? { ...rec, workspaceMap } : rec;
    let prompt = rec.imported && rec.baseBuildId ? P.importChangePrompt(promptRec, ws, refs, docsCount(rec)) : rec.baseBuildId ? P.changePrompt(ledgerBlock ? { ...promptRec, ledgerBlock } : promptRec, ws, refs) : P.initialPrompt(recipeText ? { ...rec, recipeText } : rec, ws, refs);
    let resume = null;
    let repairs = 0;
    let compileRepairs = 0; // the part of `repairs` spent on compile errors (own budget, see MAX_COMPILE_REPAIRS)
    let safetyRepairs = 0;
    let pfRepairs = 0; // repairs spent on a pre-flight failure (at most 1: a false positive can cost one repair, never the build)
    let lastErr = "";
    let nextModel = rec.model;
    let nextKind = rec.baseBuildId ? "change" : "generate";
    const assetState = { assetRepairs: 0, softAsked: false };
    const precheckSeen = new Map(); // rule|file|code -> times reported (line numbers move between attempts)
    const preKey = (h) => `${h.rule}|${h.where.split(":")[0]}|${h.evidence}`;
    for (;;) {
      rec.attempts += 1;
      placeRefs(rec, ws);
      if (libOn(rec)) SND.placeCatalog(ws);
      if (rec.imported) IMP.placeDocs(importDocsDir(rec), ws);
      try { await callClaude(rec, ctl, ws, prompt, { resume, model: nextModel, kind: nextKind }); }
      finally { dropRefs(ws); SND.dropCatalog(ws); IMP.dropDocs(ws); CAT.dropFiles(rec, WORK); ctl.draft = null; }
      CAT.collectPicks(ws, rec);
      if (ctl.assets && rec.catalog && rec.librarySlots) LA.picks(ctl.assets, rec.librarySlots, rec.catalog.pool);
      const usedModel = nextModel;
      resume = rec.sessionId;

      const summary = readSummary(ws);
      if (summary && summary.refused) {
        throw fail("refused", `We can't build this one. ${String(summary.reason || "It goes against our plugin safety rules.").slice(0, 300)}`);
      }
      sanitizeWorkspace(ws, rec);

      const secretHits = scanSecrets(listFiles(ws), [...SECRETS, ...credentialSecrets()]);
      if (secretHits.length) {
        rmrf(ws);
        log("error", "secret material found in generated source", { id: rec.id, files: secretHits });
        throw fail("safety", "The generated code was blocked by our safety checks.", "secret-scan");
      }

      setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", rec.attempts > 1 ? `Checking the fix (attempt ${rec.attempts})` : "Checking the plugin files");
      let t0 = Date.now();
      const designProblem = dsOn(rec) ? designRound(ws, rec, assetState, repairs - compileRepairs) : null;
      if (dsOn(rec)) U.addTime(rec, "design", Date.now() - t0);
      t0 = Date.now();
      const v = designProblem ? { problems: [], yml: null, fixes: [] } : validate(ws, rec);
      U.addTime(rec, "validate", Date.now() - t0);
      const roundFixes = [...(v.fixes || [])];
      let fixesRecorded = false;
      // A round whose auto-fixes ended in a clean compile is a model repair that was not needed.
      const recordFixes = (compiledOk) => {
        if (fixesRecorded || !roundFixes.length) return;
        fixesRecorded = true;
        rec.autofixes = [...(rec.autofixes || []), ...roundFixes.map((f) => ({ ...f, attempt: rec.attempts }))].slice(-40);
        rec.usage.autofix = (rec.usage.autofix || 0) + roundFixes.length;
        if (compiledOk) rec.usage.savedRepairs = (rec.usage.savedRepairs || 0) + 1;
      };
      let problem = null;
      // Known-bad API patterns for this version (reviewed rules). A hit that is
      // still there after the model was told once is left to javac, so a false
      // positive can cost at most one repair.
      if (AUTOFIX && !v.problems.length && !designProblem) {
        t0 = Date.now();
        try {
          const srcs = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
          const fx = [...AF.fixImports(srcs, rec.mcVersion, { classIndex }).fixes, ...AF.fixGameRules(srcs, rec.mcVersion, { classIndex, members }).fixes];
          if (fx.length) { roundFixes.push(...fx); event(rec, rec.status, `Fixed ${fx.length} import${fx.length > 1 ? "s" : ""} automatically`); }
          // rc12 (goblin mod): plugin.yml must declare the plugins whose API the sources import (BetterModel = depend, others = softdepend).
          if (!rec.imported) {
            const ymlP = path.join(ws, "src/main/resources/plugin.yml");
            const ymlT = fs.readFileSync(ymlP, "utf8");
            const hasCre = creOn(rec) && CR.listCreatureFiles(ws).length > 0;
            const dfx = AF.fixPluginDepends(ymlT, srcs.map((f) => fs.readFileSync(f.abs, "utf8")).join("\n"), (t) => YAML.parse(t), hasCre ? ["BetterModel"] : []);
            if (dfx) {
              fs.writeFileSync(ymlP, dfx.text);
              for (const c of dfx.changes) {
                const what = c.kind === "softdepend-add" ? `softdepend: [${c.plugin}]` : `depend: [${c.plugin}]`;
                roundFixes.push({ file: "src/main/resources/plugin.yml", line: 0, kind: c.kind, from: c.kind === "depend-move" ? `softdepend ${c.plugin}` : "missing", to: what });
                event(rec, rec.status, `Autofix: added ${what} to plugin.yml (the code uses the ${c.plugin} API; no model round)`);
              }
            }
          }
          // perf guards (leftover item drops in a loop, a raw repeating task): same behaviour, the watchdog in charge, no model turn
          // rec.perf is only set by PERF.inject inside compile(), AFTER this block: in the first round the package is derived from
          // plugin.yml (eval fourth1/third1/second1: every leftover-drop guard was skipped in round 1 and cost a model repair)
          const perfPkg = (rec.perf && rec.perf.pkg) || PERF.perfPackageOf(ws);
          if (!rec.imported && !dsOn(rec) && PERF.enabled() && perfPkg) {
            const pf = AF.fixPerf(srcs, perfPkg).fixes;
            if (pf.length) { roundFixes.push(...pf); event(rec, rec.status, `Added ${pf.filter((x) => x.kind !== "missing-import").length} performance guard${pf.length > 1 ? "s" : ""} automatically`); }
          }
        }
        catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
        U.addTime(rec, "autofix", Date.now() - t0);
      }
      t0 = Date.now();
      const assetProblem = v.problems.length || designProblem ? null : (assetRound(ws, rec, assetState, repairs - compileRepairs) || laneStep(ws, rec, assetState, repairs - compileRepairs) || (cfOn(rec) ? CFG.configRound(ws, rec, assetState, assetState.assetRepairs < MAX_ASSET_REPAIRS && repairs < MAX_REPAIRS) : null));
      const javaFiles = v.problems.length || assetProblem || designProblem ? [] : listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
      const pre = v.problems.length || assetProblem || designProblem ? [] : [...precheck(javaFiles, rec.mcVersion), ...(rec.imported || dsOn(rec) ? [] : [...PERF.perfcheck(javaFiles), ...PERF.configCheck(ws)])]
        .filter((h) => (precheckSeen.get(preKey(h)) || 0) < 1);
      U.addTime(rec, "precheck", Date.now() - t0);
      if (designProblem) {
        problem = designProblem;
        assetState.assetRepairs += 1;
      } else if (v.problems.length) {
        problem = { kind: "compile", count: v.problems.length, text: v.problems.map((p) => `- ${p}`).join("\n"), say: `${v.problems.length} setup problem${v.problems.length > 1 ? "s" : ""} found` };
      } else if (assetProblem) {
        problem = assetProblem;
        assetState.assetRepairs += 1;
      } else if (pre.length) {
        for (const h of pre) precheckSeen.set(preKey(h), (precheckSeen.get(preKey(h)) || 0) + 1);
        rec.precheck = [...(rec.precheck || []), ...pre.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
        problem = { kind: "compile", count: pre.length, text: pre.map((h) => `- ${h.where}: ${h.message}\n    ${h.evidence}`).join("\n"), say: `Pre-check found ${pre.length} known API mistake${pre.length > 1 ? "s" : ""}` };
      } else {
        setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", `Compiling against Paper ${rec.mcVersion}${rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}`);
        let c = await timedCompile(ws, rec, ctl);
        // Mechanical compile errors (wrong import package, missing API import, renamed constant
        // with exactly one right name in this version's jar) are fixed here, then recompiled,
        // before any model repair is spent. At most 2 rounds.
        for (let k = 0; !c.ok && AUTOFIX && k < 2 && !ctl.cancelled; k++) {
          t0 = Date.now();
          let fx = { fixes: [] };
          try { fx = AF.fixCompile(c.errors, ws, rec.mcVersion, { classIndex, members }); } catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
          U.addTime(rec, "autofix", Date.now() - t0);
          if (!fx.fixes.length) break;
          roundFixes.push(...fx.fixes);
          event(rec, rec.status, `Fixed ${fx.fixes.length} known API mistake${fx.fixes.length > 1 ? "s" : ""} automatically`);
          c = await timedCompile(ws, rec, ctl);
        }
        recordFixes(c.ok);
        if (ctl.cancelled) throw fail(ctl.timeout ? "timeout" : "cancelled", ctl.timeout ? "This build ran out of time." : "Build cancelled.");
        if (!c.ok) {
          const count = (c.errors.match(/^\d+ errors?$/m) || ["compile errors"])[0];
          const hints = apiHints(c.errors, ws, rec.mcVersion);
          problem = { kind: "compile", count: parseInt(count, 10) || 99, hints, text: hints ? `${c.errors.slice(0, 8000 - Math.min(hints.length, 3000))}${hints.slice(0, 3000)}` : c.errors, say: `Compiler found ${count}` };
        } else if (warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h))).length) {
          const wh = warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h)));
          for (const h of wh) precheckSeen.set(preKey(h), 1);
          rec.precheck = [...(rec.precheck || []), ...wh.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
          problem = { kind: "compile", count: wh.length, text: wh.map((h) => `- ${h.message}\n    ${h.evidence}`).join("\n"), say: `Found ${wh.length} known runtime problem${wh.length > 1 ? "s" : ""}` };
        } else {
          event(rec, rec.status, "Compiled successfully");
          setStage(rec, "scanning", "Running the safety check");
          t0 = Date.now();
          const findings = scanFindings(ws, c, rec);
          U.addTime(rec, "scan", Date.now() - t0);
          const blocks = findings.filter((f) => f.severity === "block");
          if (blocks.length) {
            if (safetyRepairs >= 1 || repairs - compileRepairs >= MAX_REPAIRS) {
              rec.safety = { verdict: "block", findings };
              throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}. Try rewording the request without that part.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
            }
            safetyRepairs += 1;
            problem = { kind: "safety", text: blocks.map((b) => `- ${b.where}: ${b.message} (${b.evidence})`).join("\n"), say: `Safety check flagged ${blocks.length} thing${blocks.length > 1 ? "s" : ""}` };
          } else {
            const warns = findings.filter((f) => f.severity === "warn");
            if (rec.scanProfile === "attested") {
              // Imported code: never "passed" or "safe", only what the attested profile found.
              rec.safety = { verdict: "warn", profile: "attested", summary: attestedSummary(findings), findings };
              event(rec, "scanning", attestedSummary(findings));
