// The public view of a ModBuild row (was in lib/modbuilder/store.ts, moved unchanged for the host seam). Pure.
import type { ModBuild } from "@prisma/client";
import type { ModBuildResult, ModBuildView } from "./types";
import { readCyrusMeta } from "../meta";

function publicCyrus(m: ReturnType<typeof readCyrusMeta>) {
  const { engineRelease, ...rest } = m;
  void engineRelease;
  return rest;
}

function publicResult(r: ModBuildResult | null): ModBuildResult | null {
  if (!r) return null;
  const { ai, ...rest } = r;
  void ai;
  return rest;
}

export function toView(row: ModBuild): ModBuildView {
  return {
    id: row.id,
    status: row.status as ModBuildView["status"],
    prompt: row.prompt,
    changeRequest: row.changeRequest,
    baseBuildId: row.baseBuildId,
    rootBuildId: row.rootBuildId,
    mcVersion: row.mcVersion,
    pluginName: row.pluginName,
    version: row.version,
    error: row.error,
    errorCode: row.errorCode,
    attempts: row.attempts,
    durationMs: row.durationMs,
    jarName: row.jarName,
    jarSize: row.jarSize,
    createdAt: row.createdAt.toISOString(),
    finishedAt: row.finishedAt ? row.finishedAt.toISOString() : null,
    result: publicResult(row.result as unknown as ModBuildResult | null),
    lastInstall: (row.lastInstall as unknown as ModBuildView["lastInstall"]) ?? null,
    cyrus: row.cyrus ? publicCyrus(readCyrusMeta(row.cyrus)) : null,
  };
}
