  events: Record<string, unknown>[];
  gap?: boolean;
  stored?: boolean;
  draft: { kind: string; path: string; op: "write" | "edit"; seq: number; from: number; text: string; total: number; done: boolean; truncated?: boolean } | null;
};
/** Cyrus r48 live assets query: events after `aseq`, and the asset draft being followed (path + tool-call seq + from). */
export type SvcLiveAssetsQuery = { aseq: number; adraft?: string; aseqd?: number; afrom?: number };

export async function svcLive(id: string, draft?: string, from?: number, seq?: number, assets?: SvcLiveAssetsQuery): Promise<SvcLive | null> {
  const n = (x: number | undefined) => Math.max(0, Math.floor(x ?? 0));
  const parts = draft ? [`draft=${encodeURIComponent(draft)}`, `seq=${n(seq)}`, `from=${n(from)}`] : [];
  if (assets) {
    parts.push("assets=1", `aseq=${n(assets.aseq)}`);
    if (assets.adraft) parts.push(`adraft=${encodeURIComponent(assets.adraft)}`, `aseqd=${n(assets.aseqd)}`, `afrom=${n(assets.afrom)}`);
  }
  const q = parts.length ? `?${parts.join("&")}` : "";
  const r = await call(`/builds/${encodeURIComponent(id)}/live${q}`, { timeoutMs: 8000 }, await workerOf(id));
  // An older service image has no /live: treat as "nothing live" rather than an error.
  if (r.status === 404) return null;
  if (!r.ok) throw new ModBuilderUnavailable(`service returned ${r.status}`);
  return (await r.json()) as SvcLive;
}

export async function svcSourceZip(id: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source.zip`, { timeoutMs: 60_000 }, await workerOf(id));

