"use client";

// The forge client (handoff lib/forge.ts): streams /api/cyrus/generate into the store and drives
// the network's beams and packets. Nxeon: a Minecraft forge is a REAL build (the stream carries its
// real progress and code, tokens are held and settled by the economy); every other game is the
// handoff's template preview. No local credits.
import { cyrusTokens } from "@/components/cyrus-tokens";
import { CATEGORY_BY_KEY, MODEL_BY_ID, categoryNodeId } from "./data";
import { diffStats } from "./engine";
import { fx } from "./fx";
import { hasListing } from "./listing-client";
import { openListing } from "./listing-ui";
import { promptProblem } from "./prompt-check";
import { pushLiveAsset } from "./liveassets/store";
import { installLiveAssetsDevHook } from "./liveassets/dev-hook";
import { gameIsLive } from "./ring";
import { isRealModId, realModId } from "./real";
import { CORE_ID, findMod, getGame, isJobLive, useStore, versionsOf, type Job } from "./store";
import type { GenEvent, Mod, ModVersion, ModelId } from "./types";

let controller: AbortController | null = null;
installLiveAssetsDevHook(); // next dev only (screenshot replay); a no-op in production

const patchJob = (fn: (job: Job) => Partial<Job>) =>
  useStore.setState((s) => (s.job ? { job: { ...s.job, ...fn(s.job) } } : {}));

export function cancelForge() {
  const job = useStore.getState().job;
  // A real build is stopped on the builder too (its held tokens are settled by the economy).
  if (job?.buildId && isJobLive(job)) void fetch(`/api/mod-builder/builds/${job.buildId}/cancel`, { method: "POST" }).catch(() => {});
  controller?.abort();
}

export type ForgeImage = { url: string; uploadId?: string };

type Ctx = { createdModId: string | null; path: string[]; rgb: string; finished: boolean; startedAt: number };

function makeHandler(ctx: Ctx) {
  // Chunks arrive faster than React needs to paint; batch them per animation frame.
  const pending = new Map<string, string>();
  let raf = 0;
  const flush = () => {
    raf = 0;
    if (!pending.size) return;
    const batch = new Map(pending);
    pending.clear();
    patchJob((job) => ({ files: job.files.map((f) => (batch.has(f.path) ? { ...f, content: f.content + batch.get(f.path) } : f)) }));
  };
  const stop = () => cancelAnimationFrame(raf);

  const handle = (ev: GenEvent) => {
    switch (ev.type) {
      case "start":
        patchJob(() => ({ id: ev.jobId, status: "thinking", credits: ev.credits, real: !!ev.real, ...(ev.real ? { buildId: ev.jobId } : {}), ...(ev.model ? { model: ev.model } : {}) }));
        break;

      case "build":
        useStore.getState().upsertReal([ev.build]);
        patchJob(() => ({ buildId: ev.build.id, real: true }));
        break;

      case "ping":
        break;

      case "asset": {
        const id = useStore.getState().job?.buildId;
        if (id) pushLiveAsset(id, ev.ev);
        break;
      }

      case "think":
        patchJob((job) => ({
          steps: [
            ...job.steps.filter((s) => s.id !== ev.id),
            { id: ev.id, label: ev.label, detail: ev.detail, done: false, startedAt: job.steps.find((s) => s.id === ev.id)?.startedAt ?? Date.now() },
          ],
        }));
        fx.ripple();
        if (ctx.path.length) fx.packets(ctx.path.slice(0, 3), 1, { rgb: ctx.rgb, speed: 1.4 });
        break;

      case "think-done":
        patchJob((job) => ({ steps: job.steps.map((s) => (s.id === ev.id ? { ...s, done: true, endedAt: Date.now() } : s)) }));
        break;

      case "route": {
        const game = getGame(ev.gameId);
        ctx.rgb = game?.rgb ?? ctx.rgb;
        ctx.path = [CORE_ID, ev.gameId, categoryNodeId(ev.gameId, ev.category), ev.modId];
        patchJob(() => ({ gameId: ev.gameId, category: ev.category, modId: ev.modId, modName: ev.modName }));
        if (!findMod(ev.modId) && !isRealModId(ev.modId)) {
          const mod: Mod = { id: ev.modId, gameId: ev.gameId, category: ev.category, name: ev.modName, summary: ev.summary, tags: ev.tags, createdAt: Date.now(), versions: [] };
          ctx.createdModId = ev.modId;
          useStore.setState((s) => ({ userMods: [...s.userMods, mod] }));
        }
        useStore.getState().select({ level: "mod", gameId: ev.gameId, category: ev.category, modId: ev.modId }, { openPanel: true, focus: "path" });
        useStore.setState({ panelTab: "code" });
        fx.setMode("forging");
        fx.startStream(ctx.path, ctx.rgb);
        fx.packets(ctx.path, 4, { rgb: ctx.rgb, speed: 1.2, size: 1.4 });
        break;
      }

      case "file":
        patchJob((job) => ({
          status: "writing",
          activeFile: ev.path,
          files: job.files.some((f) => f.path === ev.path) ? job.files : [...job.files, { path: ev.path, language: ev.language, content: "" }],
        }));
        useStore.setState({ activeFile: ev.path });
        break;

      case "chunk":
        pending.set(ev.path, (pending.get(ev.path) ?? "") + ev.text);
        if (!raf) raf = requestAnimationFrame(flush);
        break;

      case "file-set":
        // the builder rewrote or edited a file in place: replace it (after any queued chunks)
