/**
 * A new interactive build's outlook from the service's own numbers: builds of its class (and system) ahead of it, free
 * slots, and the measured run time. The wait is an approximation (waves of `concurrency` builds, the current wave half
 * done), labelled "usually about" on screen; with no measured run time there is no number.
 */
export function planCapacity(health: { concurrency?: number; capacity?: HealthCap | null } | null | undefined): PlanCapacity | null {
  const c = health?.capacity;
  if (!c || !c.running || !c.queued) return null;
  const conc = Math.max(1, Number(c.concurrency ?? health?.concurrency) || 1);
  const running = Object.values(c.running).reduce((a, b) => a + (Number(b) || 0), 0);
  const ahead = (Number(c.queued.system) || 0) + (Number(c.queued.interactive) || 0);
  if (c.breaker?.state === "open") return { state: "ai_busy", ahead, waitSec: { p50: null, p80: null } };
  const free = Math.max(0, conc - running);
  if (free > ahead) return { state: "free", ahead: 0, waitSec: { p50: 0, p80: 0 } };
