  if (p.state === "ai_busy") return "The AI is busy right now. Your build waits in line and starts by itself; nothing is charged for the wait.";
  const wait = waitPhrase(p.waitSec.p50, p.waitSec.p80);
  return `${p.ahead === 0 ? "Next for a free builder" : `${p.ahead} ${p.ahead === 1 ? "build" : "builds"} ahead of yours`}${wait ? `, usually ${wait} before it starts` : ""}.`;
}
