"use strict";
// Cyrus live progress + progress-based supervision (service 0.6+). Pure helpers, no I/O; unit-tested from the portal repo
// (test/modbuilder-progress.test.ts) with recorded stream-json samples.
//
// 1. Supervision: a model call is killed only when the CLI goes silent (no stdout or stderr for MB_IDLE_TIMEOUT_S) or at a
//    very high absolute ceiling (MB_CALL_CEILING_S / MB_BUILD_CEILING_S). MB_CALL_TIMEOUT_S / MB_BUILD_TIMEOUT_S set
//    explicitly still apply as fixed wall-clock limits (ops override). The $ budget caps are the cost guard.
// 2. Progress: a tracker turns the CLI's stream-json lines into an honest activity record (phase, current file, a short
//    sanitized hint of what the model is working through, counters, a small coalesced feed). The record is additive on the
//    build (`progress`); the old events / live view are untouched, so an old portal keeps working.
const path = require("path");
const { partialField } = require("./live");

const posInt = (v, d) => { const n = parseInt(String(v == null ? "" : v), 10); return Number.isFinite(n) && n >= 0 ? n : d; };

/** All timers, from the environment. `fixed*` = 0 means "not set explicitly: no fixed wall clock". */
function limits(env = process.env) {
  const has = (k) => env[k] !== undefined && env[k] !== "" && posInt(env[k], -1) > 0;
  return {
    idleMs: posInt(env.MB_IDLE_TIMEOUT_S, 300) * 1000, // 0 = idle supervision off
    callCeilingMs: posInt(env.MB_CALL_CEILING_S, 14400) * 1000,
    buildCeilingMs: posInt(env.MB_BUILD_CEILING_S, 21600) * 1000,
    fixedCallMs: has("MB_CALL_TIMEOUT_S") ? posInt(env.MB_CALL_TIMEOUT_S, 0) * 1000 : 0,
    fixedBuildMs: has("MB_BUILD_TIMEOUT_S") ? posInt(env.MB_BUILD_TIMEOUT_S, 0) * 1000 : 0,
    continueMax: posInt(env.MB_CONTINUE_MAX, 1),
    heartbeatMs: Math.max(3, posInt(env.MB_HEARTBEAT_S, 12)) * 1000,
    progress: env.MB_PROGRESS !== "off",
  };
}

/**
 * Watch a child process. `touch()` on every byte of output. Kills (via opts.kill) on idle / ceiling / fixed wall clock and
 * records why. Returns { touch, stop, reason }.
 */
function supervise(opts) {
  const { idleMs = 0, ceilingMs = 0, fixedMs = 0, kill, now = Date.now, tickMs = 1000 } = opts;
  const t0 = now();
  let last = t0, why = null, timer = null;
  const fire = (r) => { if (why) return; why = r; try { kill(r); } catch { /* already gone */ } };
  const check = () => {
    const t = now();
    if (fixedMs > 0 && t - t0 >= fixedMs) return fire("timeout");
    if (ceilingMs > 0 && t - t0 >= ceilingMs) return fire("ceiling");
    if (idleMs > 0 && t - last >= idleMs) return fire("idle");
  };
  timer = setInterval(check, tickMs);
  if (timer.unref) timer.unref();
  return { touch() { last = now(); }, stop() { if (timer) clearInterval(timer); timer = null; }, reason: () => why, idleFor: () => now() - last };
}

// ------------------------------------------------------------------ sanitizing ----
const REJECT = /system prompt|my instructions|the instructions|instruction[s]? (say|tell|require)|hidden|<\/?[a-z_]+>|\bapi[ _-]?key|\bsecret|password|credential|bearer|authorization|anthropic|claude code|tool_use|\bjailbreak|\bignore (the|all|previous)/i;
const SECRETISH = /\b(sk-[A-Za-z0-9_-]{8,}|[A-Fa-f0-9]{24,}|[A-Za-z0-9+/_-]{32,}={0,2}|eyJ[A-Za-z0-9_-]{10,})\b/;

/** One short, safe line out of free text, or null. First sentence, <= max chars, no host paths, no secrets, no prompt talk. */
function sanitizeHint(text, max = 140) {
  if (typeof text !== "string") return null;
  let s = text.replace(/```[\s\S]*?```/g, " ").replace(/`([^`]*)`/g, "$1").replace(/[*_#>]+/g, " ").replace(/\s+/g, " ").trim();
  if (!s) return null;
  if (SECRETISH.test(s) || REJECT.test(s)) return null;
  s = s.replace(/https?:\/\/\S+/gi, "a link").replace(/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g, "an address").replace(/\b\d{1,3}(\.\d{1,3}){3}\b/g, "an address");
  // host paths: keep only the file name
  s = s.replace(/(?:[A-Za-z]:\\|\/)(?:[\w.@ -]+[\\/])+([\w.-]+)/g, "$1");
  const m = /^(.{12,}?[.!?:])(\s|$)/.exec(s);
  s = (m ? m[1] : s).replace(/[:]$/, "").trim();
  if (s.length < 4 || /^[\W\d]+$/.test(s)) return null;
  if (s.length > max) s = s.slice(0, max - 1).replace(/\s+\S*$/, "") + "…";
  return s;
}

const SAFE_NAME = /^[A-Za-z0-9_.-]{1,80}$/;
/** The base name of a workspace path, only for src/main files (the same set the live view shows). */
function fileLabel(p) {
  if (typeof p !== "string") return null;
  const m = /(?:^|\/)src\/main\/(?:java|resources)\/(.+)$/.exec(p.replace(/\\/g, "/"));
  const base = path.posix.basename(m ? m[1] : p.replace(/\\/g, "/"));
  return SAFE_NAME.test(base) ? base : null;
}
/** "RoomBuilder.java" -> "room builder" */
function humanize(name) {
  const stem = String(name).replace(/\.[A-Za-z0-9]+$/, "");
  return stem.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/[_.-]+/g, " ").trim().toLowerCase();
}

const READ_TOOLS = new Set(["Read", "Glob", "Grep", "LS", "NotebookRead"]);
const WRITE_TOOLS = new Set(["Write", "Edit", "MultiEdit"]);

const PHASE_LABEL = {
  starting: "Starting the model",
  thinking: "Thinking",
  reading: "Reading the project",
  writing: "Writing",
  answering: "Writing up the result",
  checking: "Running checks",
  compiling: "Compiling the plugin",
  fixing: "Fixing compiler errors",
  assets: "Asset round",
  safety: "Safety check",
  flight: "Test flight",
  queued: "Waiting in line",
  continuing: "Continuing after an interruption",
};

const FEED_MAX = 80;

/** A progress tracker for one build (it spans every model call of the build). */
function newTracker(opts = {}) {
  const now = opts.now || Date.now;
  const secret = opts.hasSecret || (() => false);
  const t0 = now();
  const st = {
    phase: "starting", phaseSince: t0, file: null, lastFile: null, hint: null, hintAt: 0,
    lastStreamAt: t0, lastContentAt: t0,
    files: new Set(), edits: 0, turns: 0,
    ctx: null, // { kind: "fix"|"assets"|"safety"|"continue", round, max } set by the server around repair / continuation calls
    callN: 0, continued: 0, feed: [], seq: 0,
  };
  let thinkBuf = "", textBuf = "", hintTryAt = 0;
  const blocks = new Map(); // content block index -> { kind, json }

  const push = (k, text, extra) => {
    const t = now();
    const last = st.feed[st.feed.length - 1];
    if (k === "hb" && last && last.k === "hb") { last.at = t; last.t = text; if (extra) Object.assign(last, extra); st.seq++; return; }
    if (last && last.k === k && last.t === text) { last.at = t; return; }
    st.feed.push({ at: t, k, t: text, ...(extra || {}) });
    if (st.feed.length > FEED_MAX) st.feed.splice(0, st.feed.length - FEED_MAX);
    st.seq++;
  };
  const setPhase = (phase, file) => {
    const f = file !== undefined ? file : (phase === "writing" || phase === "reading" ? st.file : null);
    if (st.phase === phase && st.file === f) return;
    st.phase = phase; st.file = f; st.phaseSince = now();
  };
  const offerHint = (text, source) => {
    const t = now();
    if (t - hintTryAt < 4000) return;
    hintTryAt = t;
    const h = sanitizeHint(text);
    if (!h || secret(h) || h === st.hint) return;
    st.hint = h; st.hintAt = t;
    if (source) push("hint", h);
  };
  const lastSentence = (buf) => {
    const parts = buf.split(/(?<=[.!?])\s+/).filter((x) => x.trim().length > 12);
    // a finished sentence (ends with punctuation) if there is one, else the running text
    const done = parts.filter((x) => /[.!?]$/.test(x.trim()));
    return (done.length ? done[done.length - 1] : parts[parts.length - 1]) || "";
  };

  return {
    state: st,
    /** Any byte from the CLI (stdout or stderr). */
    touch() { st.lastStreamAt = now(); },
    startCall() { st.callN++; thinkBuf = ""; textBuf = ""; blocks.clear(); setPhase("thinking", null); st.lastContentAt = now(); },
    setContext(ctx) { st.ctx = ctx || null; if (ctx) push("phase", contextLabel(ctx)); },
    continued() { st.continued++; },
    note(text) { push("note", String(text).slice(0, 160)); },
    setPhase(p, label) { setPhase(p, null); if (label) push("phase", label); },
    /** One parsed stream-json line. */
    onMessage(msg) {
      if (!msg || typeof msg !== "object") return;
      st.lastStreamAt = now();
      if (msg.type === "stream_event" && msg.event) {
        const ev = msg.event;
        if (ev.type === "message_start") { st.turns++; }
        else if (ev.type === "content_block_start" && ev.content_block) {
          const cb = ev.content_block;
          if (cb.type === "tool_use") {
            blocks.set(ev.index, { kind: "tool", name: cb.name, json: "" });
            if (WRITE_TOOLS.has(cb.name)) setPhase("writing", null);
            else if (READ_TOOLS.has(cb.name)) setPhase("reading", null);
          } else if (cb.type === "thinking" || cb.type === "redacted_thinking") { blocks.set(ev.index, { kind: "thinking" }); setPhase("thinking", null); }
          else if (cb.type === "text") { blocks.set(ev.index, { kind: "text" }); setPhase("answering", null); }
          st.lastContentAt = now();
        } else if (ev.type === "content_block_delta" && ev.delta) {
          const d = ev.delta, b = blocks.get(ev.index);
          st.lastContentAt = now();
          if (d.type === "input_json_delta" && b && b.kind === "tool") {
            if (b.json.length < 1200) {
              b.json += d.partial_json || "";
              if (!b.file) {
                const fp = partialField(b.json, "file_path") || partialField(b.json, "path") || partialField(b.json, "pattern");
                const lab = fp && fp.done ? fileLabel(fp.text) : null;
                if (lab) {
                  b.file = lab;
                  if (WRITE_TOOLS.has(b.name)) { setPhase("writing", lab); push("phase", `${b.name === "Write" ? "Writing" : "Editing"} ${lab}`); }
                  else if (READ_TOOLS.has(b.name)) { setPhase("reading", lab); }
                }
              }
            }
          } else if (d.type === "thinking_delta" && typeof d.thinking === "string") {
            thinkBuf = (thinkBuf + d.thinking).slice(-2000);
            offerHint(lastSentence(thinkBuf), "think");
          } else if (d.type === "text_delta" && typeof d.text === "string") {
            textBuf = (textBuf + d.text).slice(-2000);
            offerHint(lastSentence(textBuf), "text");
          }
        } else if (ev.type === "content_block_stop") {
          const b = blocks.get(ev.index);
          if (b && b.kind === "thinking" && thinkBuf) offerHint(lastSentence(thinkBuf), "think");
          blocks.delete(ev.index);
        }
        return;
      }
      if (msg.type === "assistant" && msg.message && Array.isArray(msg.message.content)) {
        for (const c of msg.message.content) {
          if (!c || c.type !== "tool_use") continue;
          const input = c.input || {};
          const lab = fileLabel(String(input.file_path || input.path || ""));
          if (WRITE_TOOLS.has(c.name) && lab) {
            if (!st.files.has(lab)) { st.files.add(lab); push("file", `${c.name === "Write" ? "Wrote" : "Edited"} ${lab}`); }
            else { st.edits++; push("file", `Edited ${lab}`); }
            st.lastFile = lab; st.file = null;
            if (!st.hint || now() - st.hintAt > 30000) { st.hint = `Finished ${humanize(lab)}`; st.hintAt = now(); }
          } else if (READ_TOOLS.has(c.name) && lab) {
            push("phase", `Reading ${lab}`);
          }
        }
        // after a finished message the model goes back to thinking about the next step
        if (msg.message.stop_reason) setPhase("thinking", null);
      }
    },
    /** The current line a heartbeat would say. */
    headline(extra = {}) {
      const t = now();
      const secs = Math.round((t - st.phaseSince) / 1000);
      const elapsed = fmt(secs);
      const p = st.phase;
      const ctxLabel = st.ctx ? contextLabel(st.ctx) : null;
      let what;
      if (p === "writing") what = st.file ? `Writing ${st.file}` : "Writing code";
      else if (p === "reading") what = st.file ? `Reading ${st.file}` : "Reading the project";
      else if (p === "thinking") {
        const topic = st.hint && st.hintAt >= st.phaseSince - 60000 ? st.hint : st.lastFile ? `after ${humanize(st.lastFile)}` : "";
        what = topic ? `Thinking: ${topic}` : "Thinking through the design";
      } else what = PHASE_LABEL[p] || "Working";
      return ctxLabel ? `${ctxLabel}: ${what.charAt(0).toLowerCase()}${what.slice(1)}` : what + (extra.noElapsed ? "" : "") + (elapsed && p !== "writing" ? ` · ${elapsed}` : "");
    },
    /** Heartbeat: one coalesced feed line (replaces the previous heartbeat). */
    heartbeat() { push("hb", this.headline()); },
    /** The public record. All times are durations (the portal and the service clocks differ). */
    snapshot(extra = {}) {
      const t = now();
      const sec = (ms) => Math.max(0, Math.round((t - ms) / 1000));
      return {
        v: 1, asOf: t, seq: st.seq,
        phase: st.phase, headline: this.headline(), hint: st.hint, file: st.file || st.lastFile,
        phaseS: sec(st.phaseSince), quietS: sec(st.lastContentAt), streamQuietS: sec(st.lastStreamAt),
        files: st.files.size, edits: st.edits, turns: st.turns, calls: st.callN, continued: st.continued,
        ...(st.ctx ? { round: { kind: st.ctx.kind, n: st.ctx.round || 0, max: st.ctx.max || 0 } } : {}),
        ...(typeof extra.outputTokens === "number" ? { outputTokens: extra.outputTokens } : {}),
        ...(typeof extra.idleLimitS === "number" ? { idleLimitS: extra.idleLimitS } : {}),
        feed: st.feed.slice(-(extra.feedMax || 40)).map((e) => ({ ago: sec(e.at), k: e.k, t: e.t })),
      };
    },
  };
}

function contextLabel(c) {
  if (c.kind === "fix") return `Fixing compiler errors${c.round ? ` (round ${c.round}${c.max ? ` of ${c.max}` : ""})` : ""}`;
  if (c.kind === "assets") return `Asset round${c.round ? ` (${c.round}${c.max ? ` of ${c.max}` : ""})` : ""}`;
  if (c.kind === "safety") return "Fixing a safety finding";
  if (c.kind === "continue") return "Continuing where it left off";
  return "Working";
}
function fmt(secs) {
  if (secs < 60) return `${secs}s`;
  return `${Math.floor(secs / 60)}m ${String(secs % 60).padStart(2, "0")}s`;
}

/** The prompt for the one continuation call after a killed call that had already written files. */
function continuePrompt(original, files, why) {
  const list = (files || []).slice(0, 60).map((f) => `- ${f}`).join("\n");
  return `Your previous attempt on this task was interrupted (${why || "the session ended"}) before it finished. Files it had already written are in the working directory. Continue where you left off: do not rewrite files that are complete, read a file only if you need to, finish what is missing, and end exactly as the original task says.\n\nFiles that exist now:\n${list || "(none)"}\n\nThe original task, for reference:\n\n${original}`;
}

module.exports = { limits, supervise, sanitizeHint, fileLabel, humanize, newTracker, continuePrompt, PHASE_LABEL, FEED_MAX, fmt };

