// Live build progress, portal side. PURE + client-safe (unit-tested in test/cyrus-live-progress.test.ts).
// The build service (0.6+) records a small `progress` object on a build; this file bounds and sanitizes it (the service is
// not trusted), and words it for the customer: a headline, an honest "quiet" state, counters and a relative-time feed.
// Never invents anything: with no `progress` (an older service) every function says nothing and callers fall back.
import type { MbProgress } from "./types";

const KINDS = new Set(["phase", "file", "hint", "hb", "note"]);
const MAX_FEED = 40;
const int = (v: unknown, max: number): number => (typeof v === "number" && Number.isFinite(v) ? Math.max(0, Math.min(max, Math.round(v))) : 0);
const text = (v: unknown, n: number): string => (typeof v === "string" ? v.replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, n) : "");

export function progressFromService(raw: unknown): MbProgress | null {
  const r = raw as Record<string, unknown> | null | undefined;
  if (!r || typeof r !== "object" || typeof r.headline !== "string") return null;
  const feed: MbProgress["feed"] = [];
  for (const e of Array.isArray(r.feed) ? r.feed.slice(-MAX_FEED) : []) {
    const x = e as Record<string, unknown>;
    const t = text(x?.t, 160);
    if (!t || typeof x.k !== "string" || !KINDS.has(x.k)) continue;
    feed.push({ ago: int(x.ago, 86_400), k: x.k as MbProgress["feed"][number]["k"], t });
  }
  const rd = r.round as Record<string, unknown> | undefined;
  return {
    phase: text(r.phase, 24) || "working",
    headline: text(r.headline, 160),
    hint: text(r.hint, 140) || null,
    file: text(r.file, 80) || null,
    phaseS: int(r.phaseS, 86_400), quietS: int(r.quietS, 86_400), streamQuietS: int(r.streamQuietS, 86_400),
    files: int(r.files, 999), edits: int(r.edits, 9999), turns: int(r.turns, 9999), calls: int(r.calls, 99), continued: int(r.continued, 9),
    ...(rd && typeof rd === "object" ? { round: { kind: text(rd.kind, 12), n: int(rd.n, 99), max: int(rd.max, 99) } } : {}),
    ...(typeof r.outputTokens === "number" ? { outputTokens: int(r.outputTokens, 5_000_000) } : {}),
    ...(typeof r.idleLimitS === "number" ? { idleLimitS: int(r.idleLimitS, 86_400) } : {}),
    feed,
  };
}

/** "45s", "3m 20s", "1h 05m" */
export function clock(secs: number): string {
  const s = Math.max(0, Math.round(secs));
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, "0")}s`;
  return `${Math.floor(s / 3600)}h ${String(Math.floor((s % 3600) / 60)).padStart(2, "0")}m`;
}

/** "just now", "42s ago", "3m ago" */
export function ago(secs: number): string {
  const s = Math.max(0, Math.round(secs));
  if (s < 8) return "just now";
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  return `${Math.floor(s / 3600)}h ago`;
}

/** After this long with no new model output the panel says so (it is still working; the service ends a call only after the idle limit). */
export const QUIET_AFTER_S = 60;

export type ProgressNow = {
  /** the one sentence for the panel (changes at most every few seconds) */
  headline: string;
  /** "working" = output is flowing, "quiet" = no new output for a while (still working, the model is thinking), "waiting" = in line */
  state: "working" | "quiet" | "waiting";
  /** the quiet explanation, only in the quiet state */
  quietLine: string | null;
  counters: string[];
  hint: string | null;
};

/**
 * What to show at `nowMs` for a snapshot received at `receivedAt` (both the portal's clock). Durations keep counting up locally
 * between polls, so a long think still shows time moving.
 */
export function describeProgress(p: MbProgress, receivedAt: number, nowMs: number, elapsedTotalS?: number): ProgressNow {
  const since = Math.max(0, (nowMs - receivedAt) / 1000);
  const quietS = p.quietS + since;
  const quiet = quietS >= QUIET_AFTER_S && p.phase !== "compiling" && p.phase !== "safety" && p.phase !== "flight";
  const counters: string[] = [];
  if (p.files > 0) counters.push(`${p.files} file${p.files === 1 ? "" : "s"} written`);
  if (p.round && p.round.n > 0) counters.push(`repair round ${p.round.n}${p.round.max ? ` of ${p.round.max}` : ""}`);
  if (p.continued > 0) counters.push("resumed after an interruption");
  if (typeof p.outputTokens === "number" && p.outputTokens > 0) counters.push(`${p.outputTokens.toLocaleString("en-US")} tokens so far`);
  if (typeof elapsedTotalS === "number") counters.unshift(`${clock(elapsedTotalS)} elapsed`);
  const quietLine = quiet
    ? `Still working: the model is thinking${p.file ? ` about ${p.file}` : ""}. No new output for ${clock(quietS)}; this is normal for a big design.`
    : null;
  return { headline: p.headline, state: quiet ? "quiet" : "working", quietLine, counters, hint: p.hint };
}

/** The feed, newest last, with each line's age against the local clock. Heartbeats are already coalesced by the service. */
export function feedLines(p: MbProgress, receivedAt: number, nowMs: number, max = 8): { text: string; kind: string; when: string }[] {
  const since = Math.max(0, (nowMs - receivedAt) / 1000);
  return p.feed.slice(-max).map((e) => ({ text: e.t, kind: e.k, when: ago(e.ago + since) }));
}
