"use client";
// Live activity feed of a running build (shared by the studio's thinking trace and the project page's build follower).
// Honest by construction: it only says what the build service recorded (phase, file, a sanitized hint, counters), counts
// time locally between updates, and after QUIET_AFTER_S without new model output says "still working, the model is
// thinking" with the elapsed time, never "stuck". Screen readers get ONE polite status line that changes at most every 20 s;
// the feed list itself is not a live region.
import { useEffect, useRef, useState } from "react";
import { clock, describeProgress, feedLines } from "@/lib/cyrus/builder/progress-view";
import type { MbProgress } from "@/lib/cyrus/builder/types";

const CSS = `
@keyframes bact-pulse { 0%,100% { transform: scale(1); opacity: .95 } 50% { transform: scale(1.5); opacity: .45 } }
.bact-dot { width: 9px; height: 9px; border-radius: 999px; background: currentColor; flex: none; animation: bact-pulse 1.6s ease-in-out infinite; }
.bact-dot[data-state="quiet"] { animation-duration: 3.2s; }
.bact-feed { list-style: none; margin: 0; padding: 0; display: grid; gap: 3px; }
.bact-feed li { display: flex; gap: 8px; justify-content: space-between; align-items: baseline; font-size: 12px; min-width: 0; }
.bact-feed li > span:first-child { min-width: 0; overflow-wrap: anywhere; }
.bact-when { flex: none; opacity: .6; font-variant-numeric: tabular-nums; font-size: 11px; }
@media (prefers-reduced-motion: reduce) { .bact-dot { animation: none } }
`;

export function BuildActivity({ progress, receivedAt, startedAtMs, queueLine, compact }: {
  progress: MbProgress | null;
  /** portal clock time the snapshot arrived (durations in it are as of then) */
  receivedAt: number;
  /** when the build started (portal clock), for the total elapsed counter */
  startedAtMs: number;
  /** while queued: the place in line / wait (lib/cyrus/builder/queue-view.ts) */
  queueLine?: { label: string; detail: string } | null;
  compact?: boolean;
}) {
  const [now, setNow] = useState(() => Date.now());
  const [announce, setAnnounce] = useState("");
  const lastAnnounce = useRef(0);
  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, []);

  const waiting = !!queueLine && !progress;
  const d = progress ? describeProgress(progress, receivedAt, now, Math.max(0, (now - startedAtMs) / 1000)) : null;
  const headline = waiting ? queueLine!.label : d?.state === "quiet" ? "Still working, the model is thinking" : d?.headline ?? "Starting";

  useEffect(() => {
    const t = Date.now();
    if (headline && t - lastAnnounce.current > 20_000) { lastAnnounce.current = t; setAnnounce(headline); }
  }, [headline]);

  const lines = progress ? feedLines(progress, receivedAt, now, compact ? 4 : 8) : [];
  const phaseS = progress ? progress.phaseS + Math.max(0, (now - receivedAt) / 1000) : 0;
  return (
    <div data-testid="build-activity" style={{ display: "grid", gap: 6, fontSize: 13 }}>
      <style>{CSS}</style>
      <span role="status" aria-live="polite" style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>{announce}</span>
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
        <span className="bact-dot" data-state={waiting ? "wait" : d?.state ?? "working"} aria-hidden style={{ color: d?.state === "quiet" ? "#f59e0b" : "var(--cyan, #22d3ee)" }} />
        <b style={{ fontWeight: 600, overflowWrap: "anywhere" }}>{headline}</b>
        {progress && !waiting && progress.phase !== "writing" && d?.state !== "quiet" ? <span style={{ opacity: 0.65, fontSize: 12 }}>{clock(phaseS)}</span> : null}
      </div>
      {d?.quietLine ? <p style={{ margin: 0, opacity: 0.8, fontSize: 12.5 }}>{d.quietLine}</p> : null}
      {waiting ? <p style={{ margin: 0, opacity: 0.8, fontSize: 12.5 }}>{queueLine!.detail}</p> : null}
      {d?.hint && d.state !== "quiet" ? <p style={{ margin: 0, opacity: 0.75, fontSize: 12.5, fontStyle: "italic", overflowWrap: "anywhere" }}>{d.hint}</p> : null}
      {d && d.counters.length ? <div style={{ display: "flex", gap: "2px 12px", flexWrap: "wrap", opacity: 0.7, fontSize: 11.5 }}>{d.counters.map((c) => <span key={c}>{c}</span>)}</div> : null}
      {lines.length ? (
        <ol className="bact-feed" aria-label="Build activity">
          {lines.map((l, i) => (
            <li key={`${i}-${l.text}`}><span>{l.text}</span><span className="bact-when">{l.when}</span></li>
          ))}
        </ol>
      ) : null}
    </div>
  );
}
