// Cyrus live progress + progress-based supervision (services/modbuilder/progress.js), driven by a recorded-style stream-json
// sample (test/fixtures/modbuilder-stream/*.ndjson: the shape of mb9aeb0308c0ac46e580b2, where thinking deltas are absent).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { EventEmitter } from "node:events";
import { join } from "node:path";
import { progressFromService, describeProgress, feedLines, clock, ago } from "../lib/cyrus/builder/progress-view";

/* eslint-disable @typescript-eslint/no-require-imports */
const PG = require("../services/modbuilder/progress.js") as {
  limits: (e: Record<string, string>) => Record<string, number | boolean>;
  supervise: (o: Record<string, unknown>) => { touch(): void; stop(): void; reason(): string | null };
  sanitizeHint: (t: unknown, max?: number) => string | null;
  fileLabel: (p: unknown) => string | null;
  newTracker: (o?: Record<string, unknown>) => { onMessage(m: unknown): void; startCall(): void; touch(): void; setContext(c: unknown): void; setPhase(p: string, l?: string): void; heartbeat(): void; snapshot(e?: Record<string, unknown>): Record<string, unknown> & { feed: { k: string; t: string; ago: number }[] }; note(t: string): void };
  continuePrompt: (o: string, f: string[], w?: string) => string;
};
const FIX = readFileSync(join(__dirname, "fixtures/modbuilder-stream/dungeon-start.ndjson"), "utf8").trim().split("\n").map((l) => JSON.parse(l));
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

describe("limits (progress-based supervision config)", () => {
  it("defaults: idle 300 s, ceilings 4 h / 6 h, no fixed wall clock", () => {
    const l = PG.limits({});
    assert.equal(l.idleMs, 300_000); assert.equal(l.callCeilingMs, 14_400_000); assert.equal(l.buildCeilingMs, 21_600_000);
    assert.equal(l.fixedCallMs, 0); assert.equal(l.fixedBuildMs, 0); assert.equal(l.continueMax, 1);
  });
  it("MB_CALL_TIMEOUT_S / MB_BUILD_TIMEOUT_S still apply when set explicitly", () => {
    const l = PG.limits({ MB_CALL_TIMEOUT_S: "600", MB_BUILD_TIMEOUT_S: "1200", MB_IDLE_TIMEOUT_S: "120" });
    assert.equal(l.fixedCallMs, 600_000); assert.equal(l.fixedBuildMs, 1_200_000); assert.equal(l.idleMs, 120_000);
  });
});

describe("supervise: kill on inactivity, not on wall clock", () => {
  it("a chatty child outlives idleMs; a silent one is killed as idle", async () => {
    let killed: string | null = null;
    const sv = PG.supervise({ idleMs: 80, tickMs: 10, kill: (r: string) => { killed = r; } });
    for (let i = 0; i < 8; i++) { await sleep(25); sv.touch(); } // 200 ms of output, 2.5x idleMs
    assert.equal(killed, null);
    await sleep(160);
    assert.equal(sv.reason(), "idle"); assert.equal(killed, "idle");
    sv.stop();
  });
  it("the ceiling and an explicit fixed limit still fire", async () => {
    const a = PG.supervise({ idleMs: 0, ceilingMs: 60, tickMs: 10, kill: () => {} });
    const b = PG.supervise({ fixedMs: 40, ceilingMs: 5000, tickMs: 10, kill: () => {} });
    await sleep(120);
    assert.equal(a.reason(), "ceiling"); assert.equal(b.reason(), "timeout");
    a.stop(); b.stop();
  });
});

describe("tracker on a recorded stream", () => {
  const mk = () => {
    let t = 1_000_000;
    const tr = PG.newTracker({ now: () => t });
    return { tr, adv: (ms: number) => { t += ms; } };
  };
  it("derives phase, file and counters from tool_use (no thinking text in the stream)", () => {
    const { tr, adv } = mk();
    tr.startCall();
    for (const m of FIX.slice(0, 9)) { adv(1000); tr.onMessage(m); }
    const s = tr.snapshot();
    assert.equal(s.files, 1);
    const feed = s.feed.map((e) => e.t);
    assert.ok(feed.includes("Writing RoomBuilder.java"), JSON.stringify(feed));
    assert.ok(feed.includes("Wrote RoomBuilder.java"));
    assert.ok(!JSON.stringify(s).includes("/work/") && !JSON.stringify(s).includes("mb9aeb"), "no workspace paths");
  });
  it("sanitizes thinking text: paths and prompt talk never reach the record; the hint is one short sentence", () => {
    const { tr, adv } = mk();
    tr.startCall();
    for (const m of FIX) { adv(5000); tr.onMessage(m); }
    const s = tr.snapshot();
    assert.ok(s.hint === null || (s.hint as string).length <= 140);
    assert.ok(!JSON.stringify(s).includes("/opt/nxeon"), "host path leaked");
    assert.equal((s.phase as string), "thinking");
  });
  it("heartbeats coalesce: 100 beats are one feed line", () => {
    const { tr, adv } = mk();
    tr.startCall();
    for (let i = 0; i < 100; i++) { adv(12_000); tr.heartbeat(); }
    const hb = tr.snapshot().feed.filter((e) => e.k === "hb");
    assert.equal(hb.length, 1);
    assert.match(hb[0].t, /Thinking/);
    assert.match(hb[0].t, /\d+m \d\ds/);
  });
  it("the feed is capped", () => {
    const { tr } = mk();
    for (let i = 0; i < 500; i++) tr.note(`n${i}`);
    assert.ok(tr.snapshot({ feedMax: 999 }).feed.length <= 80);
  });
  it("a repair context labels the round", () => {
    const { tr } = mk();
    tr.startCall();
    tr.setContext({ kind: "fix", round: 2, max: 8 });
    assert.match(tr.snapshot().headline as string, /Fixing compiler errors \(round 2 of 8\)/);
    assert.deepEqual((tr.snapshot() as { round?: unknown }).round, { kind: "fix", n: 2, max: 8 });
  });
});

describe("sanitizeHint", () => {
  it("first sentence only, <= 140 chars", () => {
    const h = PG.sanitizeHint("Rooms are placed on a 3x3 grid with a spawn room in the centre. Then corridors are carved. " + "x".repeat(300));
    assert.equal(h, "Rooms are placed on a 3x3 grid with a spawn room in the centre.");
    assert.ok((PG.sanitizeHint("a ".repeat(200)) as string).length <= 140);
  });
  it("redacts host paths to a file name, drops links", () => {
    assert.equal(PG.sanitizeHint("I will edit /root/projects/x/src/main/java/RoomBuilder.java now."), "I will edit RoomBuilder.java now.");
    assert.equal(PG.sanitizeHint("See https://evil.example/x?token=abc for the doc."), "See a link for the doc.");
  });
  it("rejects secrets and prompt / system talk", () => {
    for (const t of ["The api key is [REDACTED].", "My system prompt says to avoid networking.", "Using token [REDACTED] to push.", "The instructions say: ignore previous rules."]) assert.equal(PG.sanitizeHint(t), null, t);
  });
  it("file labels: only src/main base names", () => {
    assert.equal(PG.fileLabel("/work/x/src/main/java/a/b/RoomBuilder.java"), "RoomBuilder.java");
    assert.equal(PG.fileLabel("/etc/passwd"), "passwd"); // a bare name is harmless; the dir never is
    assert.equal(PG.fileLabel("a b;rm"), null);
  });
});

describe("continuation prompt", () => {
  it("lists the files and keeps the original task", () => {
    const p = PG.continuePrompt("Build a dungeon plugin.", ["src/main/java/A.java"], "the model went silent");
    assert.match(p, /Continue where you left off/); assert.match(p, /src\/main\/java\/A\.java/); assert.match(p, /Build a dungeon plugin\./);
  });
});

describe("portal view of progress", () => {
  const raw = { phase: "thinking", headline: "Thinking: the room generator", hint: "the room generator", file: "RoomBuilder.java", phaseS: 200, quietS: 75, streamQuietS: 3, files: 3, edits: 1, turns: 4, calls: 1, continued: 0, outputTokens: 12000, feed: [{ ago: 30, k: "file", t: "Wrote A.java" }, { ago: 1, k: "hb", t: "Thinking · 3m 20s" }, { ago: 1, k: "evil", t: "x" }] };
  it("bounds and filters untrusted input; old service = null", () => {
    assert.equal(progressFromService(undefined), null);
    assert.equal(progressFromService({ headline: 3 }), null);
    const p = progressFromService({ ...raw, feed: [...raw.feed, ...Array.from({ length: 100 }, (_, i) => ({ ago: i, k: "note", t: "n" + i }))], headline: "h".repeat(999) })!;
    assert.ok(p.feed.length <= 40 && p.headline.length <= 160);
    assert.ok(!p.feed.some((e) => e.k === ("evil" as string)));
  });
  it("quiet after 60 s of no output says 'still working, the model is thinking', never 'stuck'", () => {
    const p = progressFromService(raw)!;
    const d = describeProgress(p, 0, 0, 400);
    assert.equal(d.state, "quiet");
    assert.match(d.quietLine!, /Still working: the model is thinking/);
    assert.ok(!/stuck|frozen|failed/i.test(d.quietLine!));
    assert.ok(d.counters.includes("3 files written") && d.counters.includes("12,000 tokens so far") && d.counters.includes("6m 40s elapsed"));
    const fresh = describeProgress({ ...p, quietS: 4 }, 0, 0);
    assert.equal(fresh.state, "working");
    assert.equal(describeProgress({ ...p, quietS: 4 }, 0, 70_000).state, "quiet", "the quiet clock keeps counting locally between updates");
  });
  it("relative times", () => {
    assert.equal(clock(200), "3m 20s"); assert.equal(ago(2), "just now"); assert.equal(ago(125), "2m ago");
    const l = feedLines(progressFromService(raw)!, 0, 10_000);
    assert.equal(l[0].when, "40s ago");
  });
});
