function sanitizeHint(text, max = 140) {
  if (typeof text !== "string") return null;
  let s = text.replace(/```[\s\S]*?```/g, " ").replace(/`([^`]*)`/g, "$1").replace(/[*_#>]+/g, " ").replace(/\s+/g, " ").trim();
  if (!s) return null;
  // host paths: keep only the file name; links and addresses are not shown
  s = s.replace(/https?:\/\/\S+/gi, "a link").replace(/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g, "an address").replace(/\b\d{1,3}(\.\d{1,3}){3}\b/g, "an address");
  s = s.replace(/(?:[A-Za-z]:\\|\/)(?:[\w.@ -]+[\\/])+([\w.-]+)/g, "$1");
  const m = /^(.{12,}?[.!?:])(\s|$)/.exec(s);
  s = (m ? m[1] : s).replace(/[:]$/, "").trim();
  if (SECRETISH.test(s) || REJECT.test(s)) return null;
  if (s.length < 4 || /^[\W\d]+$/.test(s)) return null;
  if (s.length > max) s = s.slice(0, max - 1).replace(/\s+\S*$/, "") + "…";
  return s;
}
