describe("modbuilder live progress + idle supervision (real server.js, fake CLI)", () => {
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-prog-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", "#!/usr/bin/env node\\n"]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\\n");
    const nodePath = path.join(dir, "node_modules");
    try { require.resolve("yaml", { paths: [SVC] }); } catch { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    port = 39000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", NODE_PATH: nodePath,
        MB_CONCURRENCY: "3", MB_IDLE_TIMEOUT_S: "2", MB_HEARTBEAT_S: "3",
      } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { svcErr += d; });
    for (let i = 0; i < 100; i++) {
      try { if ((await health()).ok) return; } catch { /* starting */ }
      await sleep(100);
    }
    throw new Error(`service did not start: ${svcErr.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("/health states the supervision limits (no wall-clock default)", async () => {
    const h = await health();
    assert.equal(h.features.progress.idleTimeoutS, 2);
    assert.equal(h.features.progress.callCeilingS, 14400);
    assert.equal(h.features.progress.buildCeilingS, 21600);
    assert.equal(h.features.progress.fixedCallS, null);
    assert.equal(h.features.progress.continueMax, 1);
  });

  it("a call that keeps producing output outlives the idle limit, and the build shows live progress while it runs", async () => {
    assert.equal((await api("POST", "/builds", { id: "mbprogchat01", prompt: P("CHATTY a"), mcVersion: "1.21.11" })).status, 202);
    let seen: Record<string, any> | null = null;
    const end = Date.now() + 15_000;
    while (Date.now() < end) {
      const j = (await api("GET", "/builds/mbprogchat01")).j;
      if (j.progress && j.progress.feed.length && j.status !== "succeeded") seen = j.progress;
      if (done(j)) break;
      await sleep(150);
    }
    const fin = await waitFor("mbprogchat01", done);
    assert.equal(fin.status, "succeeded", JSON.stringify(fin.events?.map((e: { message: string }) => e.message)));
    assert.ok(fin.durationMs > 4000, "ran longer than 2x the idle limit");
    assert.ok(seen, "progress was visible while running");
    assert.equal(typeof seen!.headline, "string");
    assert.ok(Array.isArray(seen!.feed) && seen!.feed.length <= 80);
    assert.ok(fin.progress && fin.progress.feed.length > 0, "the finished record keeps the feed");
    assert.ok(fin.progress.feed.filter((e: { k: string }) => e.k === "hb").length <= 1, "heartbeats are coalesced");
  });

  it("killed on silence AFTER files were written: one continuation finishes the build, nothing fails", async () => {
    assert.equal((await api("POST", "/builds", { id: "mbprogcont01", prompt: P("SILENTAFTERWRITE a"), mcVersion: "1.21.11" })).status, 202);
    const fin = await waitFor("mbprogcont01", done, 40_000);
    assert.equal(fin.status, "succeeded", JSON.stringify({ e: fin.events?.map((x: { message: string }) => x.message), err: fin.error }));
    assert.ok(fin.events.some((e: { message: string }) => /Continuing from the \\d+ files already written/.test(e.message)));
    const kinds = fin.aiCalls.map((c: { kind: string }) => c.kind);
    assert.ok(kinds.includes("generate") && kinds.includes("generate-continue"), JSON.stringify(kinds));
    const killed = fin.aiCalls.find((c: { killedBy?: string }) => c.killedBy);
    assert.equal(killed.killedBy, "idle");
    assert.ok(fin.costUsd >= 0.05, "the real usage of the completed call is charged");
    assert.equal(fin.progress.continued, 1);
  });

  it("silent from the start with nothing written: fails once, honestly, without a continuation", async () => {
    assert.equal((await api("POST", "/builds", { id: "mbprogsil001", prompt: P("SILENTNOW a"), mcVersion: "1.21.11" })).status, 202);
    const fin = await waitFor("mbprogsil001", done, 30_000);
    assert.equal(fin.status, "failed");
    assert.equal(fin.errorCode, "timeout");
    assert.match(fin.error, /stopped responding/);
    assert.ok(!fin.aiCalls.some((c: { kind: string }) => /continue/.test(c.kind)));
  });
});
