"use strict";
// Nxeon Mod Builder build service.
//
// POST /builds                 {id, prompt, mcVersion, pluginName?, baseBuildId?, changeRequest?, tier?, images?, assets?} -> 202
//                              images (0.4+): [{name, type, data: base64}] up to 4 PNG/JPEG/WebP/GIF, 5 MB each.
//                              They are placed in the build workspace (reference/) for the model to Read.
//                              assets (Cyrus R1): {texture, sound, namespace} decided by the PORTAL's plan-tier gate.
//                              texture=true lets the model write texture specs (assets/textures/<name>.json, checked
//                              by textures.js and returned in `assetResult`); absent = the pre-R1 behaviour exactly.
//                              sound=true lets it write sound specs (assets/sounds/<set>.json, checked by sounds.js);
//                              creature=true (R3, 26.x + BetterModel API installed) lets it write RigSpecs
//                              (assets/creatures/<name>.json, checked by creatures.js) and compile against BetterModel;
//                              library=true also places the sound library catalog (portal: licence cleared).
// GET  /builds/:id             status + events + result
// GET  /builds/:id/artifact    the plugin .jar
// GET  /builds/:id/source?path=src/main/java/...   one source file (text). While the build runs (0.4+) this
//                              reads the LIVE workspace, src/main/** only, secret-scanned on the way out.
// GET  /builds/:id/live?draft=<path>&seq=<n>&from=<n>   (0.4+) live view while running: src/main/** file list
//                              (size + short hash) and the file the model is writing right now, streamed
//                              from the par
